import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import api from "../api";

const ROLES = [
  {id:"student", label:"Student",  emoji:"🎓", placeholder:"email@example.com"},
  {id:"company", label:"Company",  emoji:"🏢", placeholder:"hr@company.com"},
  {id:"admin",   label:"Admin",    emoji:"🏛️", placeholder:"admin@stag.io"},
];

export default function Login() {
  const [role, setRole]         = useState("student");
  const [email, setEmail]       = useState(""); 
  const [password, setPassword] = useState("");
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading]   = useState(false);
  
  const navigate = useNavigate();
  const cfg = ROLES.find(r => r.id === role);

  const handleLogin = async (e) => {
    e.preventDefault();
    if (!email || !password) {
      alert("Please enter both email and password");
      return;
    }

    setLoading(true);
    try {
      const response = await api.post('login/', {
        username: email, // Django JWT uses 'username' by default
        password: password
      });

      localStorage.setItem('access_token', response.data.access);
      localStorage.setItem('refresh_token', response.data.refresh);

      // Get user profile to confirm role
      const profileRes = await api.get('profile/');
      const userRole = profileRes.data.role.toLowerCase();
      localStorage.setItem('userRole', userRole);

      // Redirect based on role
      if (userRole === "student") navigate("/student/dashboard");
      else if (userRole === "company") navigate("/company/dashboard");
      else if (userRole === "admin") navigate("/admin/dashboard");

    } catch (error) {
      console.error("Login error:", error.response?.data);
      alert(error.response?.data?.detail || "Invalid credentials. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex bg-[#fdf9f5]">
      <div className="hidden lg:flex lg:w-[52%] bg-slate-900 flex-col justify-center px-12 relative overflow-hidden">
        <h1 className="text-white text-5xl font-extrabold leading-tight z-10">
          Your internship <br/> journey starts <span className="text-blue-400">here.</span>
        </h1>
        <div className="absolute inset-0 opacity-20 dot-grid"></div>
      </div>

      <div className="flex-1 flex flex-col justify-center items-center px-8">
        <div className="w-full max-w-md">
          <h2 className="text-3xl font-bold text-slate-900 mb-8">Sign In</h2>

          <div className="bg-slate-100 rounded-xl p-1 flex mb-6">
            {ROLES.map(r => (
              <button key={r.id} onClick={() => setRole(r.id)}
                className={`flex-1 py-2 rounded-lg text-sm font-medium transition-all ${role===r.id ? "bg-white text-slate-900 shadow-sm" : "text-slate-500"}`}>
                {r.label}
              </button>
            ))}
          </div>

          <form onSubmit={handleLogin} className="space-y-4">
            <input 
              type="email" 
              value={email} 
              onChange={e=>setEmail(e.target.value)} 
              placeholder={cfg.placeholder} 
              className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500" 
            />
            <div className="relative">
              <input 
                type={showPass ? "text" : "password"} 
                value={password} 
                onChange={e=>setPassword(e.target.value)} 
                placeholder="Password" 
                className="w-full p-3 border rounded-xl outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button type="button" onClick={()=>setShowPass(!showPass)} className="absolute right-3 top-3 text-slate-400">
                {showPass ? "🙈" : "👁️"}
              </button>
            </div>
            <button 
              type="submit"
              disabled={loading}
              className={`w-full py-3 rounded-xl text-white font-bold transition-all ${loading ? "bg-slate-400" : "bg-slate-900 hover:bg-slate-800"}`}
            >
              {loading ? "Signing in..." : "Sign In →"}
            </button>
          </form>
          <p className="mt-6 text-center text-sm text-slate-500">
            Don't have an account? <Link to="/register" className="text-blue-600 font-bold">Register</Link>
          </p>
        </div>
      </div>
    </div>
  );
}
